#include "move.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"OW_CHECK OMM line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static int base(void){OwAllocator a={0};OwOwner src={0},dst={0},busy={0};size_t n[3]={1,2,3};CHECK(ow_construct(&src,ow_allocator(&a),n)==OW_OK&&ow_construct(&busy,ow_allocator(&a),n)==OW_OK);CHECK(ow_move(&src,&src)==OW_INVALID);CHECK(ow_move(&busy,&src)==OW_INVALID&&src.count==3&&busy.count==3);CHECK(ow_move(&dst,&src)==OW_OK&&dst.count==3&&!src.count);for(unsigned i=0;i<3;++i)CHECK(src.block[i]==NULL);CHECK(ow_consume(&src)==OW_DEAD&&ow_consume(&dst)==OW_OK&&ow_consume(&dst)==OW_DEAD);CHECK(ow_destroy(&busy)==OW_OK&&a.live==0&&a.releases==6);puts("OMM_BASE actual-move consume source-poison occupied-refusal");return 0;}
static int inline_value(void){OwAllocator a={0};int32_t data[8]={11,12,13,14,15,16,17,18};for(size_t n=1;n<=8;++n){OmmValue src={0},dst={0};CHECK(omm_init(&src,ow_allocator(&a),data,n)==OW_OK);int32_t *old_data=src.data;OmmValue copied=src;int32_t value=91;CHECK(omm_read(&copied,0,&value)==OW_INVALID&&value==91);CHECK(omm_move(&dst,&src)==OW_OK&&!src.live&&src.data==NULL&&src.self==NULL&&dst.self==&dst);CHECK(dst.data==(n<=4?dst.small:old_data));for(size_t i=0;i<n;++i)CHECK(omm_read(&dst,i,&value)==OW_OK&&value==data[i]);CHECK(omm_consume(&src)==OW_DEAD&&omm_consume(&dst)==OW_OK&&omm_consume(&dst)==OW_DEAD);}CHECK(a.attempts==4&&a.releases==4&&!a.live);puts("OMM_INLINE self-address repaired inline-versus-heap raw-copy-rejected");return 0;}
static int admission(void){OwAllocator a={0};a.fail_at=1;OmmValue src={0},dst={0};int32_t data[8]={0};CHECK(omm_init(&src,ow_allocator(&a),data,5)==OW_NOMEM&&!src.live&&!src.data&&!src.self);CHECK(omm_init(&src,ow_allocator(&a),data,0)==OW_INVALID&&a.attempts==1);CHECK(omm_init(&src,ow_allocator(&a),data,3)==OW_OK);CHECK(omm_init(&dst,ow_allocator(&a),data,2)==OW_OK);CHECK(omm_move(&dst,&src)==OW_INVALID&&dst.length==2&&src.length==3);CHECK(omm_move(&src,&src)==OW_INVALID);int32_t out=91;CHECK(omm_read(&src,3,&out)==OW_INVALID&&out==91);CHECK(omm_consume(&dst)==OW_OK&&omm_consume(&src)==OW_OK);puts("OMM_ADMISSION actual-allocation-failure unchanged-owners bounds");return 0;}
static void *harness_allocations[16];
typedef struct {unsigned calls,releases,fail,empty;size_t bytes;OmmRegistry **owner;} Heap;
static void *take(void *p,size_t n){Heap *h=p;++h->calls;h->bytes=n;if(h->fail)return NULL;void *value=malloc(n);if(!value)return NULL;for(unsigned i=0;i<16;++i)if(!harness_allocations[i]){harness_allocations[i]=value;return value;}free(value);return NULL;}
static void release(void *p,void *value){Heap *h=p;++h->releases;h->empty=h->owner&&*h->owner==NULL;for(unsigned i=0;i<16;++i)if(harness_allocations[i]==value)harness_allocations[i]=NULL;free(value);}
static int registry(void){OwAllocator a={0};Heap h={0};OmmRegistry *r=NULL;h.owner=&r;OmmMemory m={&h,take,release};h.fail=1;CHECK(omm_registry_create(m,ow_allocator(&a),0,&r)==OW_NOMEM&&!r);h.fail=0;CHECK(omm_registry_create(m,ow_allocator(&a),0,&r)==OW_OK);int32_t data[8]={21,22,23,24,25,26,27,28},value=91;OmmToken t={0},dst={0};CHECK(omm_token_open(r,data,8,&t)==OW_OK);OmmToken copied=t;CHECK(omm_registry_destroy(&r)==OW_BUSY&&r&&h.releases==0);CHECK(omm_token_move(r,&dst,&t)==OW_OK&&!t.owner);CHECK(omm_token_read(r,copied,0,&value)==OW_STALE&&value==91);CHECK(omm_token_read(r,dst,7,&value)==OW_OK&&value==28);CHECK(omm_token_consume(r,&copied)==OW_STALE&&a.live==1);OmmToken duplicate=dst;CHECK(omm_token_consume(r,&dst)==OW_OK&&!a.live&&a.releases==1);CHECK(omm_token_consume(r,&duplicate)==OW_STALE&&a.releases==1);OmmToken reopened={0};CHECK(omm_token_open(r,data,1,&reopened)==OW_OK&&reopened.slot==duplicate.slot&&reopened.generation>duplicate.generation);value=91;CHECK(omm_token_read(r,duplicate,0,&value)==OW_STALE&&value==91);OmmRegistry *other=NULL;Heap h2={0};h2.owner=&other;CHECK(omm_registry_create((OmmMemory){&h2,take,release},ow_allocator(&a),0,&other)==OW_OK);CHECK(omm_token_read(other,reopened,0,&value)==OW_STALE&&value==91);CHECK(omm_registry_destroy(&other)==OW_OK);CHECK(omm_token_consume(r,&reopened)==OW_OK);CHECK(omm_registry_destroy(&r)==OW_OK&&!r&&h.releases==1&&h.empty);puts("OMM_REGISTRY opaque-representation rotating-authority duplicate-stale actual-regions");return 0;}
static int theft(void){OwAllocator a={0};Heap h={0};OmmRegistry *r=NULL;h.owner=&r;CHECK(omm_registry_create((OmmMemory){&h,take,release},ow_allocator(&a),0,&r)==OW_OK);int32_t data[1]={51},out=91;OmmToken owner={0},attacker={0};CHECK(omm_token_open(r,data,1,&owner)==OW_OK);OmmToken stolen=owner;CHECK(omm_token_move(r,&attacker,&stolen)==OW_OK);CHECK(omm_token_read(r,owner,0,&out)==OW_STALE&&out==91);CHECK(omm_token_read(r,attacker,0,&out)==OW_OK&&out==51);CHECK(omm_token_consume(r,&attacker)==OW_OK&&omm_registry_destroy(&r)==OW_OK);puts("OMM_THEFT identical-live-copy-can-win no-holder-authentication harmless-local-only");return 0;}
static int retirement(void){OwAllocator a={0};Heap h={0};OmmRegistry *r=NULL;h.owner=&r;CHECK(omm_registry_create((OmmMemory){&h,take,release},ow_allocator(&a),UINT32_MAX-1,&r)==OW_OK);int32_t data[5]={1,2,3,4,5};OmmToken first={0},dst={0};CHECK(omm_token_open(r,data,5,&first)==OW_OK&&first.generation==UINT32_MAX);OmmToken before=first;CHECK(omm_token_move(r,&dst,&first)==OW_RETIRED&&!dst.owner&&first.generation==before.generation);CHECK(omm_token_consume(r,&first)==OW_OK);CHECK(omm_token_open(r,data,5,&first)==OW_OK&&first.slot==1&&first.generation==UINT32_MAX);CHECK(omm_token_consume(r,&first)==OW_OK);CHECK(omm_token_open(r,data,5,&first)==OW_FULL&&!first.owner&&a.attempts==2);CHECK(omm_registry_destroy(&r)==OW_OK&&!a.live&&a.releases==2);puts("OMM_RETIREMENT final-generation-consumable slots-retire no-wrap-reuse");return 0;}
static int oracle(void){unsigned n,seed,op;while(scanf("%u %u %u",&n,&seed,&op)==3){OwAllocator a={0};Heap h={0};OmmRegistry *r=NULL;h.owner=&r;if(omm_registry_create((OmmMemory){&h,take,release},ow_allocator(&a),seed,&r)!=OW_OK)return 1;int32_t data[8]={1,2,3,4,5,6,7,8};OmmToken live={0},copy={0};OwStatus s=omm_token_open(r,data,n,&live);copy=live;printf("%d %u",s,live.generation);for(unsigned k=0;k<op;++k){OmmToken dst={0};s=omm_token_move(r,&dst,&live);printf(" %d",s);if(s==OW_OK)live=dst;}int32_t v=91;OwStatus read=omm_token_read(r,copy,0,&v);printf(" %d %d %u",read,v,live.generation);if(live.owner){if(omm_token_consume(r,&live)!=OW_OK)return 1;}printf(" %zu %zu\n",a.attempts,a.releases);if(omm_registry_destroy(&r)!=OW_OK)return 1;}return ferror(stdin)?2:0;}
static int metrics(void){OwAllocator a={0};int32_t data[3]={1,2,3};unsigned sum=0;double times[7];for(unsigned s=0;s<7;++s){clock_t start=clock();for(unsigned i=0;i<10000;++i){OmmValue src={0},dst={0};int32_t out;CHECK(omm_init(&src,ow_allocator(&a),data,3)==OW_OK&&omm_move(&dst,&src)==OW_OK&&omm_read(&dst,2,&out)==OW_OK&&omm_consume(&dst)==OW_OK);sum+=(unsigned)out;}times[s]=(double)(clock()-start)/CLOCKS_PER_SEC;}Heap h={0};OmmRegistry *r=NULL;h.owner=&r;CHECK(omm_registry_create((OmmMemory){&h,take,release},ow_allocator(&a),0,&r)==OW_OK&&omm_registry_destroy(&r)==OW_OK);printf("{\"iterations\":10000,\"checksum\":%u,\"typed_allocation_attempts\":%zu,\"value_size\":%zu,\"token_size\":%zu,\"registry_bytes\":%zu,\"raw_allocations\":%u,\"raw_releases\":%u,\"seconds\":[",sum,a.attempts,sizeof(OmmValue),sizeof(OmmToken),h.bytes,h.calls,h.releases);for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",times[i]);puts("]}");return 0;}
static int run(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"move_base"))return base();if(!strcmp(argv[1],"move_inline"))return inline_value();if(!strcmp(argv[1],"move_admission"))return admission();if(!strcmp(argv[1],"move_registry"))return registry();if(!strcmp(argv[1],"move_theft"))return theft();if(!strcmp(argv[1],"move_retirement"))return retirement();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}

int main(int argc,char **argv){int result=run(argc,argv);for(unsigned i=0;i<16;++i)free(harness_allocations[i]);return result;}
